def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find and remove the solid gray band.
    gray_rows = [r for r in range(h) if all(v == 3 for v in grid[r])]
    gray_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 3:
                out[r][c] = 0

    # Motifs are 4x4 or 3x3, separated by one blank row/column.
    n = 4 if h == 19 else 3
    step = n + 1
    count = (h + 1) // step

    # The tile at the upper-left gives the occupancy pattern for the
    # larger arrangement of tiles.
    motif = [row[:n] for row in grid[:n]]

    for i in range(count):
        for j in range(count):
            if motif[i][j] != 2:
                continue
            r0, c0 = i * step, j * step

            # Reconstruct this tile from the canonical motif, including
            # any tile hidden under the gray band.
            for dr in range(n):
                for dc in range(n):
                    if not (r0 + dr < h and c0 + dc < w):
                        continue
                    if (r0 + dr in gray_rows or c0 + dc in gray_cols):
                        out[r0 + dr][c0 + dc] = motif[dr][dc]

            # Encode the tile's position with an 8 at its indexed motif cell.
            rr, cc = r0 + i, c0 + j
            if rr < h and cc < w and out[rr][cc] == 2:
                out[rr][cc] = 8

    return out
